<?php require_once __DIR__.'/../api/bootstrap.php';require_login();$m=current_medico();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT a.*,p.nome paciente_nome,p.cpf paciente_cpf FROM atestados a JOIN pacientes p ON p.id=a.paciente_id WHERE a.id=? AND a.medico_id=?');$s->execute([$id,$m['id']]);$a=$s->fetch();if(!$a)exit('Atestado não encontrado.');$body=trim((string)$a['conteudo_personalizado']);if($body==='')$body='Atesto, para os devidos fins, que <strong>'.e($a['paciente_nome']).'</strong> foi submetido(a) a avaliação médica. Conforme avaliação, apresenta condição registrada sob CID-10 <strong>'.e($a['cid_codigo']).'</strong> — '.e($a['cid_descricao']).'. Necessita de afastamento/restrição das atividades no período de <strong>'.e(date('d/m/Y',strtotime($a['inicio_afastamento']))).' a '.e(date('d/m/Y',strtotime($a['fim_afastamento']))).'</strong>, totalizando <strong>'.e($a['dias_afastamento']).' dia(s)</strong>.';else$body=nl2br(e($body));?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title><?=e($a['titulo'])?></title><style>body{font:15px Arial;max-width:820px;margin:30px auto;line-height:1.65}.doc{border:1px solid #ddd;padding:45px;min-height:900px}.sign{text-align:center;margin-top:90px}.meta{font-size:12px;color:#666}@media print{.no-print{display:none}body{margin:0}.doc{border:0}}</style></head><body><div class="no-print"><button onclick="print()">Imprimir / Salvar PDF</button></div><article class="doc"><h1 style="text-align:center"><?=e($a['titulo']?:'ATESTADO MÉDICO')?></h1><p><?=$body?></p><?php if($a['atividade_habitual']):?><p><b>Atividade habitual:</b> <?=e($a['atividade_habitual'])?></p><?php endif;?><?php if($a['incapacidade_restricao']):?><p><b>Limitação/restrição:</b> <?=nl2br(e($a['incapacidade_restricao']))?></p><?php endif;?><?php if($a['info_clinica']):?><p><b>Informações clínicas:</b> <?=nl2br(e($a['info_clinica']))?></p><?php endif;?><?php if($a['observacoes']):?><p><b>Observações:</b> <?=nl2br(e($a['observacoes']))?></p><?php endif;?><p><?=date('d/m/Y',strtotime($a['data_emissao']))?></p><div class="sign"><?php if(!empty($m['assinatura_path'])&&file_exists(__DIR__.'/../'.$m['assinatura_path'])):?><img src="/medical/<?=e($m['assinatura_path'])?>" style="max-width:220px;max-height:90px"><br><?php endif;?><b><?=e($m['nome_completo'])?></b><br>CRM <?=e($m['crm'].'/'.$m['uf'])?></div><hr><div class="meta">Código: <?=e($a['codigo_validacao'])?><br>Validação: https://<?=e($_SERVER['HTTP_HOST'])?>/medical/validar.php?id=<?=e($a['codigo_validacao'])?></div></article></body></html>